INSERT INTO knowledge.source_claim (id, chunk_id, claim_code, claim_text, claim_kind, knowledge_type, contract, confidence) VALUES
   ('089394a8-a0c1-5b61-83f9-69d92de109f7', 'f2674e8e-a424-57bf-9fa4-77041e198690', 'HCH1-0001', 'Clinical Methods is the set of skills doctors use to diagnose and treat disease, and the manner in which doctors approach clinical problems and relate to patients.', 'definition', 'clinical_method', '{"what_is_it": "Clinical methods (definition)", "why": "Frames the entire clinical-assessment skill set.", "source_support": "Hutchison 24e ch1 p14"}'::jsonb, 0.9),
   ('c0632e6d-8621-56a0-a75a-206a35bdb738', 'f2674e8e-a424-57bf-9fa4-77041e198690', 'HCH1-0002', 'There are two main steps to making a diagnosis: (1) establish the clinical features by history and examination (the clinical database); (2) interpret that database in terms of disordered function and potential causative pathologies (physical, mental, social, or a combination).', 'principle', 'clinical_method', '{"what_is_it": "Two-step diagnostic process", "what_connects_to": "differential reasoning interface", "source_support": "Hutchison 24e ch1 p14"}'::jsonb, 0.9),
   ('24f39610-6177-5ba2-bd84-7ede2a478488', 'f2674e8e-a424-57bf-9fa4-77041e198690', 'HCH1-0003', 'Symptoms are what the patient reports or complains of (e.g. cough, headache); signs are findings on observation or physical examination.', 'question', 'clinical_method', '{"what_is_it": "symptom vs sign definition", "what_fact_produces": "symptom presence facts vs examination facts", "source_support": "Hutchison 24e ch1 p14"}'::jsonb, 0.9),
   ('30712c40-4b9c-510c-a3b8-6826d7db77ad', '2af5df4d-86e0-5fe3-81cd-c79c22de8ace', 'HCH1-0004', 'Begin the history with a single open-ended question such as ''Tell me about what has led up to you coming here today'', leaving as open as possible any question about the cause of the patient''s problems.', 'question', 'clinical_method', '{"what_is_it": "opening question (open-ended)", "question_mode": "OPEN", "what_activates_it": "start of any history", "where_documented": "history of presenting complaint opening", "source_support": "Hutchison 24e ch1 p15"}'::jsonb, 0.9),
   ('52c208ef-2f31-5ec6-8b59-73c0029e2fef', '2af5df4d-86e0-5fe3-81cd-c79c22de8ace', 'HCH1-0005', 'There is particular logic in taking the past medical history before the presenting complaint, because for many conditions the distinction between current problem and past history is unclear and arbitrary in the patient''s mind; taking the history along a timeline builds a better picture.', 'history_section', 'clinical_method', '{"what_is_it": "schematic history order — past medical history first", "when_applies": "non-emergency new-patient history", "where_documented": "past medical history section", "source_support": "Hutchison 24e ch1 p15"}'::jsonb, 0.9),
   ('3d2b5030-9b74-5179-8068-1b9775cbc225', '2af5df4d-86e0-5fe3-81cd-c79c22de8ace', 'HCH1-0006', 'Box 1.1 beginning-history question areas: confirm date of birth and age; occupation and occupational history; past medical history; smoking; alcohol consumption; drug and treatment history; family history.', 'rule', 'clinical_method', '{"what_is_it": "beginning history checklist", "what_fact_produces": "demographics, occupation, smoking, alcohol, drugs, family history facts", "where_documented": "background/social history", "source_support": "Hutchison 24e ch1 p15 Box 1.1"}'::jsonb, 0.9),
   ('1561faec-d1cf-51bc-8cc5-b0978b01eb8e', '5c956642-2036-5c8b-95a1-e77d56f5d3a2', 'HCH1-0007', 'Vocabulary must be clarified: ordinary English words (diarrhoea, constipation, wind, indigestion, being sick, dizziness, headache, double vision, pins and needles, rash, blister) and medical terms patients use imprecisely (arthritis, sciatica, migraine, fits, stroke, palpitation, angina, heart attack, nausea, piles/haemorrhoids, anaemia, pleurisy, eczema, urticaria, warts, cystitis) require clarification of meaning.', 'question', 'clinical_method', '{"what_is_it": "vocabulary clarification list", "question_mode": "CLARIFYING", "what_fact_produces": "clarified symptom interpretation", "source_support": "Hutchison 24e ch1 p16 Box 1.3"}'::jsonb, 0.9),
   ('4576cb2a-0896-588e-95cd-81e7deefdee7', '8c809990-b114-57d3-8ba1-1bed1232d5c2', 'HCH1-0008', 'Indirect/open-ended questions invite the patient to talk about a general area (''Tell me more about...'', ''What do you think about...'', ''How does that make you feel...'', ''What happened next...'', ''Is there anything else you would like to tell me?''); direct/closed questions elicit yes/no answers.', 'question', 'clinical_method', '{"what_is_it": "indirect vs direct question types", "question_mode": "OPEN vs DIRECT", "source_support": "Hutchison 24e ch1 p17"}'::jsonb, 0.9),
   ('67e4e52a-6228-5458-8faa-1be16aaea65b', '8c809990-b114-57d3-8ba1-1bed1232d5c2', 'HCH1-0009', 'A patient-centred interview contains enough open-ended questions for patients to talk about all their problems and enough time to do so; an interview using many direct questions tends to be disease-centred.', 'principle', 'clinical_method', '{"what_is_it": "patient-centred vs disease-centred interview", "source_support": "Hutchison 24e ch1 p17"}'::jsonb, 0.9),
   ('cf6d43b4-db39-5df5-9250-7860e3eaf7c5', '8c809990-b114-57d3-8ba1-1bed1232d5c2', 'HCH1-0010', 'Box 1.4 pitfall: leading closed questions (''Is it in the middle of your chest? Does it travel to your left arm? Does it come on when you walk? Is it relieved by rest?'') railroad the diagnosis; open questions plus clarifying questions preserve an open mind.', 'rule', 'clinical_method', '{"what_is_it": "leading-question anti-pattern", "question_mode": "OPEN then CLARIFYING preferred over leading DIRECT", "source_support": "Hutchison 24e ch1 p17 Box 1.4"}'::jsonb, 0.9),
   ('dee4ca14-6e59-57d5-a18b-010e8246b4de', 'fc6e0351-3567-5e45-b540-1697d1c19b3d', 'HCH1-0011', 'Judging severity: ask ''How much does this bother you?'' and probe daily-life impact (Box 1.5): exercise tolerance (how far can you walk on the flat at your own speed; climb one flight of stairs slowly; do simple housework), work (kept off work; why), sport (affected?), eating (affected; particular foods), social life (restricted; sex life affected).', 'question', 'clinical_method', '{"what_is_it": "severity/functional-impact probing", "question_mode": "FUNCTIONAL", "what_fact_produces": "functional impact facts (mobility, work, sport, eating, social)", "where_documented": "functional impact", "source_support": "Hutchison 24e ch1 p18 Box 1.5"}'::jsonb, 0.9),
   ('333265af-aaf6-567c-b146-52412b640138', 'fc6e0351-3567-5e45-b540-1697d1c19b3d', 'HCH1-0012', 'Pain severity is rated on a scale 1-10, where 1 is barely noticeable and 10 is the worst pain the patient can imagine or has ever experienced; clarify the reference point for ''10''.', 'question', 'clinical_method', '{"what_is_it": "pain numeric rating scale", "what_fact_produces": "PAIN_SEVERITY_SCORE", "when_applies": "any pain complaint", "source_support": "Hutchison 24e ch1 p18"}'::jsonb, 0.9),
   ('1d805376-74b6-5fc8-81ec-cf4bc2542911', 'fc6e0351-3567-5e45-b540-1697d1c19b3d', 'HCH1-0013', 'Suggested scheme for basic history taking (Box 1.6): name/age/occupation/country of birth; main presenting problem; past medical history (all serious problems in the whole of life); specific past medical history (diabetes, jaundice, TB, heart disease, high blood pressure, rheumatic fever, epilepsy); history of main presenting complaint; family history; occupational history; smoking, alcohol, allergies; drug and other treatment history; direct questions about bodily systems not covered by the presenting complaint.', 'history_section', 'clinical_method', '{"what_is_it": "schematic history (canonical order)", "where_documented": "entire history structure", "source_support": "Hutchison 24e ch1 p18 Box 1.6"}'::jsonb, 0.9),
   ('6c8698af-3474-56b2-8de3-93a30bccc3b7', 'a65cbc26-5a1b-54be-892c-e59d9eccc19b', 'HCH1-0014', 'Direct questions about bodily systems (Box 1.7): cardiorespiratory (chest pain, intermittent claudication, palpitation, ankle swelling, orthopnoea, nocturnal dyspnoea, shortness of breath, cough with/without sputum, haemoptysis); gastrointestinal (abdominal pain, dyspepsia, dysphagia, nausea and/or vomiting, appetite, weight loss/gain, bowel pattern and change, rectal bleeding, jaundice); genitourinary (haematuria, nocturia, frequency, dysuria, menstrual irregularity in women, urethral discharge in men); locomotor (joint pain, change in mobility); neurological (seizures, collapses, dizziness, eyesight, hearing, transient loss of function, paraesthesia).', 'question', 'clinical_method', '{"what_is_it": "systems review question set", "question_mode": "DIRECT", "when_applies": "systems not covered by presenting complaint", "what_fact_produces": "review-of-systems presence facts", "where_documented": "review of systems", "source_support": "Hutchison 24e ch1 p19 Box 1.7"}'::jsonb, 0.9),
   ('85d28fa3-0768-55a4-8735-806e78bb165d', 'a65cbc26-5a1b-54be-892c-e59d9eccc19b', 'HCH1-0015', 'Pain clarification (Box 1.8): site, radiation, character, severity, time course, aggravating factors, relieving factors, associated symptoms.', 'question', 'clinical_method', '{"what_is_it": "universal pain exploration dimensions", "question_mode": "CLARIFYING", "what_fact_produces": "pain site/radiation/character/severity/timing/aggravators/relievers/associations", "source_support": "Hutchison 24e ch1 p19 Box 1.8"}'::jsonb, 0.9),
   ('75fb5b05-62f7-5860-8fbd-87227e9161b7', 'ca0a3a70-e472-520c-bb6a-5e0d072b550d', 'HCH1-0016', 'Drug-history clarifying questions (Box 1.9): all drugs/medicines taken; prescribed from another clinic/doctor/dentist; bought from a pharmacy; all tablets/capsules/liquids; inhalers, skin creams, patches, suppositories, lozenges; medicines stopped recently; medicines prescribed for other people; herbal or complementary medicines.', 'question', 'clinical_method', '{"what_is_it": "comprehensive drug history probe set", "question_mode": "DIRECT + CLARIFYING", "what_fact_produces": "complete medication list incl. OTC, complementary, recently stopped", "where_documented": "drug history", "source_support": "Hutchison 24e ch1 p20 Box 1.9"}'::jsonb, 0.9),
   ('b7bbaacb-d7a7-55ed-8e55-6d12b71b3df9', 'ca0a3a70-e472-520c-bb6a-5e0d072b550d', 'HCH1-0017', 'Family-history detail (Box 1.10): illnesses that run in the family; a basic family tree of first-degree relatives (with major illnesses, cause and age of deaths); specific questions about problems similar to the patient''s and items in the developing differential diagnosis (e.g. gallstones, epilepsy, high blood pressure).', 'question', 'clinical_method', '{"what_is_it": "family history structure", "what_fact_produces": "family history facts, genetic risk", "where_documented": "family history", "source_support": "Hutchison 24e ch1 p20 Box 1.10"}'::jsonb, 0.9),
   ('143760b7-2abd-5a36-b872-38103aa79d96', 'ca0a3a70-e472-520c-bb6a-5e0d072b550d', 'HCH1-0018', 'Occupational history is taken chronologically from leaving school forwards; a careful chronological occupational history may be required to elucidate exposures that act years later (e.g. asbestosis, silicosis).', 'history_section', 'clinical_method', '{"what_is_it": "occupational history method", "question_mode": "CONTEXT", "what_fact_produces": "occupational exposure history", "source_support": "Hutchison 24e ch1 p20, ch12 p181"}'::jsonb, 0.9),
   ('bb8bfea6-d18d-5290-a659-86d1c0ebf9c5', 'ca0a3a70-e472-520c-bb6a-5e0d072b550d', 'HCH1-0019', 'Alcohol history: probe in different ways rather than taking the patient''s word; convert reported amounts to units of alcohol per week (units = volume ml x %abv / 1000); UK recommendation is less than 14 units/week; assess dependency with CAGE (Cut down, Angry, Guilty, Eye-opener — two or more positives may indicate dependency).', 'history_section', 'clinical_method', '{"what_is_it": "alcohol history + CAGE screen", "question_mode": "PROBING", "what_fact_produces": "alcohol units/week, CAGE score, dependency risk", "source_support": "Hutchison 24e ch1 p20 Boxes 1.11-1.13"}'::jsonb, 0.9),
   ('c9d798f3-a56c-556f-a76f-9bcef09df40f', 'a68ecc70-3ace-50e7-b99d-4e8651df423b', 'HCH1-0020', 'Hard vs soft symptoms (Box 1.15): a hard symptom, if clearly present, adds a lot of weight to a particular diagnosis (e.g. pneumaturia→colovesical fistula; fortification spectra with unilateral headache→classical migraine; rigors→bacteraemia/viraemia/malaria; bitten tongue with a seizure→grand mal; sudden severe headache ''like a hammer blow''→subarachnoid haemorrhage; pleuritic chest pain→pleural irritation; itching with jaundice→cholestasis). Soft symptoms are reported variably or present in many conditions and do not confirm or refute a diagnosis (e.g. dizziness, light-headedness, tiredness, back pain, headache, wind).', 'definition', 'clinical_method', '{"what_is_it": "evidence class of symptoms", "what_fact_produces": "qualitative evidence weight for differential scoring", "source_support": "Hutchison 24e ch1 p23 Box 1.15"}'::jsonb, 0.9),
   ('05b44086-7a46-5a92-8680-d883c79b740d', 'a68ecc70-3ace-50e7-b99d-4e8651df423b', 'HCH1-0021', 'Time course: the character of a symptom suggests the ''anatomy'' of the problem and the time course the ''pathology''. A vascular event (myocardial infarction, stroke, subarachnoid haemorrhage) usually has sudden onset; gradually progressing or undatable-onset symptoms (weight loss, dysphagia) may be malignant.', 'principle', 'clinical_method', '{"what_is_it": "time-course analysis principle", "what_fact_produces": "onset/duration/trajectory facts", "source_support": "Hutchison 24e ch1 p23-24"}'::jsonb, 0.9),
   ('a49b18dd-d087-5764-b26c-fe4ec08cf371', '8e0c4d28-902f-5e88-a427-05976f1018c6', 'HCH1-0022', 'Negative data: ask specific yes/no questions for which a negative answer is as important as a positive one (e.g. for exertional chest pain, whether pain is worse on increased exertion and how long a rest relieves it).', 'question', 'clinical_method', '{"what_is_it": "negative-data probing", "question_mode": "NEGATIVE/EXCLUSION", "what_fact_produces": "explicitly-recorded negative findings", "source_support": "Hutchison 24e ch1 p24"}'::jsonb, 0.9),
   ('86c6d2d2-3d32-5dcd-93b6-110c9940d3b8', '8e0c4d28-902f-5e88-a427-05976f1018c6', 'HCH1-0023', 'What the patient actually wants (Box 1.16) should be explored: cannot tolerate ongoing symptoms; someone else noticed a problem; another doctor noticed a problem; worry about an underlying diagnosis; spouse/relative worried; cannot work with symptoms; colleagues/bosses complaining; requirement of others (insurance, employment benefit, litigation).', 'question', 'clinical_method', '{"what_is_it": "reason-for-consultation exploration", "question_mode": "CONTEXT", "what_fact_produces": "reason_for_consultation fact", "source_support": "Hutchison 24e ch1 p24 Box 1.16"}'::jsonb, 0.9),
   ('3d2fab8a-2d66-51cf-97c1-81bdcc523507', 'de8d40b7-e012-5d07-88e9-9d2ad65c38d3', 'HCH2-0001', 'The separation of history from examination is artificial; the examination starts with the first greeting and ends when the patient departs, and physical findings may prompt further questioning (history and exam are iterative, not linear).', 'principle', 'clinical_method', '{"what_is_it": "history-exam iteration principle", "source_support": "Hutchison 24e ch2 p26"}'::jsonb, 0.9),
   ('ca4a5f05-7afa-5a43-92c4-0e5c48af3827', 'de8d40b7-e012-5d07-88e9-9d2ad65c38d3', 'HCH2-0002', 'Global assessment first: ask ''Does this person look well, mildly ill or severely ill?''; if severely ill, postpone detailed examination until the acute situation is attended to.', 'examination', 'clinical_method', '{"what_is_it": "severity triage during examination", "when_applies": "start of every examination", "source_support": "Hutchison 24e ch2 p26"}'::jsonb, 0.9),
   ('001a2dc6-27fb-50e3-95a0-5cd23ea7401c', '8c453bdd-55d8-518b-8d9a-e7b0bc5ebc51', 'HCH2-0003', 'General examination components: posture and gait; speech and interaction; physique and nutrition (BMI; cachexia; central vs generalised obesity; muscle wasting); temperature (mouth 35.8-37C, ear/rectum 0.5C higher, axilla 0.5C lower; diurnal variation; persistent/remittent/intermittent fever patterns); hands (handshake, wasting, tremor, clubbing with Lovibond''s angle and Schamroth''s window, Dupuytren''s contracture); odours (alcohol, acetone in DKA, hepatic/uraemic foetor, halitosis); face and neck (facial nerve palsy, parotid swelling, malar flush of mitral stenosis, butterfly rash of SLE, telangiectasia, scleroderma furrowing, JVP); lymph glands; axillae; skin (temperature, hydration, turgor, pallor, jaundice, cyanosis peripheral vs central); pulses (radial, femoral, popliteal, dorsalis pedis, posterior tibial); blood pressure (+postural drop >20/10 within 3 min supine→upright); legs and feet (colour, texture, hair, oedema, varicose veins, DVT); breasts; then a structured ''putting it all together'' sequence.', 'examination', 'clinical_method', '{"what_is_it": "universal general-examination object set", "what_fact_produces": "examination facts (BMI, temperature, clubbing, oedema, cyanosis, pulse character, BP, JVP...)", "where_documented": "examination section of clinical documentation", "source_support": "Hutchison 24e ch2 p27-37"}'::jsonb, 0.9),
   ('f4bfc379-4cca-5393-b374-5d4730c61de2', '3f9dc54f-0fc8-5930-8629-b5ac9fe92a80', 'HCH2-0004', 'Suggested complete-examination order (Box 2.5): general; mouth and pharynx; hands; cardiovascular and respiratory (anterior, semi-recumbent); cardiovascular and respiratory (posterior, sitting forward); neck (sitting forward); abdomen; upper limbs; lower limbs; cranial nerves.', 'examination', 'clinical_method', '{"what_is_it": "complete examination sequence", "where_documented": "examination documentation order", "source_support": "Hutchison 24e ch2 p38"}'::jsonb, 0.9),
   ('90f4576e-d241-523b-bfde-70b3b56884e4', 'afbcb817-849d-54b8-ab44-7e63d53ca41d', 'HCH2-0005', 'Differential diagnosis framework (Box 2.3) — pathological processes to consider: Congenital, Degenerative, Infective/inflammatory, Metabolic, Neoplastic, Nutritional, Toxic, Traumatic, Vascular.', 'management', 'clinical_method', '{"what_is_it": "differential diagnosis sieve", "what_activates_it": "any differential reasoning", "source_support": "Hutchison 24e ch2 p39 Box 2.3"}'::jsonb, 0.9),
   ('334d02a0-8f2d-5858-96f4-530decc28cd9', 'afbcb817-849d-54b8-ab44-7e63d53ca41d', 'HCH2-0006', 'Order of tasks for a provisional management plan (Box 2.4): (1) list monitoring/nursing recommendations imperative to immediate comfort and safety; (2) list investigations to do immediately; (3) document medications to prescribe with doses and frequency (including IV fluids); (4) list investigations that may be needed later for further diagnostic information.', 'management', 'clinical_method', '{"what_is_it": "management plan construction order", "source_support": "Hutchison 24e ch2 p39 Box 2.4"}'::jsonb, 0.9),
   ('a61405f8-3749-5b66-be51-36b5ad111364', '84b86844-5df6-5504-b4cb-b7f9ab74644c', 'HCH12-0001', 'Most patients with respiratory disease present with breathlessness, cough, excess sputum, haemoptysis, wheeze or chest pain.', 'definition', 'clinical_method', '{"what_is_it": "respiratory cardinal symptoms", "what_connects_to": "symptom registry for respiratory system", "source_support": "Hutchison 24e ch12 p178"}'::jsonb, 0.9),
   ('6ff56941-8803-5ea4-89b5-ca621877d24f', '84b86844-5df6-5504-b4cb-b7f9ab74644c', 'HCH12-0002', 'Dyspnoea is breathlessness inappropriate to the level of physical exertion, or occurring at rest; it may be due to cardiac disease, anaemia, thyrotoxicosis or metabolic acidosis as well as primary respiratory problems.', 'definition', 'clinical_method', '{"what_is_it": "dyspnoea definition", "what_connects_to": "cardiac, haematological, endocrine, metabolic systems", "source_support": "Hutchison 24e ch12 p178 Box 12.1"}'::jsonb, 0.9),
   ('0f4d78d4-e4d0-5b39-bbb1-8b5b99553b7e', '84b86844-5df6-5504-b4cb-b7f9ab74644c', 'HCH12-0003', 'Dyspnoea clarification: is it related only to exertion and how far can the patient walk at a normal pace on the level (exercise tolerance); is there variability, good days and bad days; are there times of day or night that are worse (asthma worse at night/early morning vs COPD mainly exertional).', 'question', 'clinical_method', '{"what_is_it": "dyspnoea exploration dimensions", "question_mode": "CLARIFYING + FUNCTIONAL", "what_fact_produces": "MRC dyspnoea grade, exercise tolerance, diurnal variation", "source_support": "Hutchison 24e ch12 p178"}'::jsonb, 0.9),
   ('21c209f6-d624-5c2b-9efb-65fd732da8d1', '84b86844-5df6-5504-b4cb-b7f9ab74644c', 'HCH12-0004', 'Cough is defined as acute if it lasts less than 3 weeks and chronic if it lasts more than 8 weeks; any cough associated with haemoptysis requires prompt assessment and at least a baseline chest X-ray; any chronic cough (>8 weeks) should have CXR and spirometry as baseline investigations.', 'threshold', 'clinical_method', '{"what_is_it": "cough duration thresholds + baseline investigation triggers", "what_fact_produces": "COUGH_DURATION, chronic-cough flags", "what_activates_it": "CXR + spirometry for chronic cough", "source_support": "Hutchison 24e ch12 p178 Box 12.3-12.4"}'::jsonb, 0.9),
   ('96fe40dc-026c-5244-a91d-76c3bc31a2f9', '84b86844-5df6-5504-b4cb-b7f9ab74644c', 'HCH12-0005', 'Cough discussion should include: how long has the cough been present; is the cough worse at any time of day or night (dry cough at night/spasms may be asthma); is the cough aggravated by anything (allergic triggers: dust, animals, pollen; non-specific triggers: exercise, cold air); severe coughing may be followed by vomiting.', 'question', 'clinical_method', '{"what_is_it": "cough exploration dimensions", "question_mode": "CLARIFYING + PROBING", "what_fact_produces": "cough duration, timing, triggers, post-tussive vomiting", "source_support": "Hutchison 24e ch12 p178"}'::jsonb, 0.9),
   ('b400a2b9-eadd-591f-b0c9-ccef076e27eb', 'ad08340b-21cf-59e0-abb8-b57cc1b2585d', 'HCH12-0006', 'Sputum clarification: is sputum produced; what does it look like (colour, consistency — yellow/green usually purulent; thick/jelly-like with casts in asthma; eosinophilic purulent appearance without infection); how much is produced (a cupful daily suggests bronchiectasis; smaller amounts in chronic bronchitis).', 'question', 'clinical_method', '{"what_is_it": "sputum exploration dimensions", "question_mode": "CLARIFYING", "what_fact_produces": "sputum volume, colour, purulence, consistency", "source_support": "Hutchison 24e ch12 p179"}'::jsonb, 0.9),
   ('2c90d815-f495-5f00-9049-55d12c9270d6', 'ad08340b-21cf-59e0-abb8-b57cc1b2585d', 'HCH12-0007', 'Haemoptysis (coughing up blood) should never be dismissed without very careful evaluation; a specific question is always necessary (fear often leads patients not to mention it); decide if fresh or altered blood, how much, when it started and how often; ask about epistaxis and subsequent melaena.', 'red_flag', 'clinical_method', '{"what_is_it": "haemoptysis red flag", "urgency": "urgent", "what_activates_it": "investigation (CXR at least)", "source_support": "Hutchison 24e ch12 p179-180 Box 12.6"}'::jsonb, 0.9),
   ('7a56ac96-931c-5808-b56c-2d8bd4a9c38d', 'be39ba92-5159-5139-b62b-59e3e188c473', 'HCH12-0008', 'Wheezing: always ask whether the patient hears any noises coming from the chest; wheezing may be noticed by others (partner at night) and not by the patient; distinguish wheeze from stridor (stridor indicates narrowing of the larynx, trachea or main bronchi).', 'question', 'clinical_method', '{"what_is_it": "wheeze exploration", "question_mode": "DIRECT", "what_fact_produces": "wheeze presence, audibility, stridor vs wheeze distinction", "source_support": "Hutchison 24e ch12 p180"}'::jsonb, 0.9),
   ('62df47c1-a9d2-5512-bfad-335b49ac64b1', 'be39ba92-5159-5139-b62b-59e3e188c473', 'HCH12-0009', 'Chest pain in respiratory disease: pleuritic pain is sharp and stabbing, worsened by deep breathing or coughing, and occurs when the pleura is inflamed (most commonly infection); constant pain unrelated to breathing may indicate local invasion of the chest wall by tumour; spontaneous pneumothorax pain is worse on breathing but more aching; pulmonary embolus can cause pleuritic pain, non-stabbing pain, or cardiac-type pain with haemodynamic disturbance.', 'differential', 'clinical_method', '{"what_is_it": "respiratory chest pain differential", "what_fact_produces": "pleuritic character, relation to breathing, pain constancy", "source_support": "Hutchison 24e ch12 p180"}'::jsonb, 0.9),
   ('54e708c7-98f1-58ca-a804-907d3e8ce548', 'be39ba92-5159-5139-b62b-59e3e188c473', 'HCH12-0010', 'Respiratory history upper-airway/ENT: rhinosinusitis often coexists with asthma or bronchiectasis and can aggravate; postnasal drip from rhinitis is a common cause of chronic cough; change in voice may indicate left recurrent laryngeal nerve involvement by lung carcinoma; hoarseness persisting >4 weeks warrants laryngoscopy.', 'question', 'clinical_method', '{"what_is_it": "ENT/upper-airway dimensions of respiratory history", "what_fact_produces": "rhinosinusitis, postnasal drip, hoarseness duration", "source_support": "Hutchison 24e ch12 p180"}'::jsonb, 0.9),
   ('c5f02776-6d58-506a-9fea-608514e34d8c', 'be39ba92-5159-5139-b62b-59e3e188c473', 'HCH12-0011', 'Full smoking and recreational drug history is required: ''Do you smoke?'' is not enough; record age of starting and stopping for ex-smokers, average consumption for current and ex-smokers (pack-years); recreational drugs (heroin, crack, cannabis) are smoked and can damage the lungs; take the history sympathetically and non-judgementally.', 'question', 'clinical_method', '{"what_is_it": "smoking + recreational drug history", "question_mode": "PROBING", "what_fact_produces": "smoking status, pack-years, recreational drug exposure", "source_support": "Hutchison 24e ch12 p180"}'::jsonb, 0.9),
   ('cd393f90-054e-5a33-a104-c057115aa7de', 'a98d2bad-b93b-5d70-9de3-673116f476b5', 'HCH12-0012', 'Family history: strong inherited susceptibility to asthma; associated atopic conditions (eczema, hay fever) may be present in relatives of those with asthma, particularly when onset is young.', 'risk_factor', 'clinical_method', '{"what_is_it": "asthma/atopy family history", "what_fact_produces": "family history of asthma/atopy", "source_support": "Hutchison 24e ch12 p181"}'::jsonb, 0.9),
   ('f0ecf5d1-d352-517b-937f-a370a6894346', 'a98d2bad-b93b-5d70-9de3-673116f476b5', 'HCH12-0013', 'Occupational history: no other organ is as susceptible to the working environment as the lungs; several hundred substances cause occupational asthma (car paint sprayers/isocyanates, woodworkers, bakers/flour dust, animals, hairdressing, healthcare/latex); always ask about the relationship between symptoms and work; asbestos exposure (mining, shipbuilding, construction, lagging, car mechanics, family exposure) may take decades to manifest as malignant mesothelioma.', 'risk_factor', 'clinical_method', '{"what_is_it": "occupational respiratory risk factors", "question_mode": "PROBING + CONTEXT", "what_fact_produces": "occupational exposure facts (dusts, isocyanates, asbestos)", "source_support": "Hutchison 24e ch12 p181 Boxes 12.7-12.8"}'::jsonb, 0.9),
   ('f6e86af0-e187-52b3-944e-816ed1e9bbd4', 'a98d2bad-b93b-5d70-9de3-673116f476b5', 'HCH12-0014', 'Respiratory general assessment (Box 12.9): physique and gait; voice; breathlessness (accessory muscles, pursed lips in COPD); clubbing of the fingers; tobacco staining; bruising/thin skin; venous pulses; cyanosis or pallor; ptosis; swollen face; collateral vessels across anterior chest wall; intercostal recession; use of accessory respiratory muscles; lymph nodes.', 'examination', 'clinical_method', '{"what_is_it": "respiratory general assessment object set", "what_fact_produces": "respiratory general examination facts", "source_support": "Hutchison 24e ch12 p181 Box 12.9"}'::jsonb, 0.9),
   ('62a51e79-494b-5a3a-b220-862d8c78bf54', '16565e0a-5b19-5495-8b54-935a97b97178', 'HCH12-0015', 'Hands in respiratory examination (Box 12.10): clubbing (respiratory causes: carcinoma of the bronchus, pulmonary fibrosis, bronchiectasis, lung abscess, empyema), pallor, cyanosis, warm well-perfused palms (CO2 retention), flap (hypercapnia), tremor (inhaled beta2-agonists), tobacco staining, bruising/thin skin, pulse rate and character (raised in significant asthma attack; pulsus paradoxus degree measures asthma severity).', 'examination', 'clinical_method', '{"what_is_it": "respiratory hand examination", "what_fact_produces": "clubbing, CO2 retention flap, tremor, pulse facts", "source_support": "Hutchison 24e ch12 p182 Box 12.10"}'::jsonb, 0.9),
   ('4442cb00-23b8-5765-8bd1-d44fe611c8b8', '16565e0a-5b19-5495-8b54-935a97b97178', 'HCH12-0016', 'Respiratory rate and rhythm: normal adult rate ~14-16 breaths/min; tachypnoea is increased rate observed by the doctor, dyspnoea is the symptom experienced by the patient; apnoea is cessation of respiration; Cheyne-Stokes breathing (cyclical deepening/quickening then diminishing with apnoeic pauses) occurs in severe cardiac failure, narcotic poisoning and neurological disorders; obstructive sleep apnoea is commoner in obese patients.', 'examination', 'clinical_method', '{"what_is_it": "respiratory rate/rhythm examination", "what_fact_produces": "respiratory rate, breathing pattern facts", "source_support": "Hutchison 24e ch12 p182-183 Box 12.11"}'::jsonb, 0.9),
   ('fe877fd3-c9bf-5c20-a0ef-c15cfc5a4db8', '4ab382a7-0ba1-53bb-a2ed-eca5128076cc', 'HCH12-0017', 'Chest examination sequence: look (inspection — scars, shape, symmetry, movement, intercostal recession, barrel chest/overinflation), then feel (palpation — lymph nodes, swellings, tenderness, tracheal position, chest expansion, tactile vocal fremitus), then percuss (resonance/dullness, comparing sides), then listen (auscultation — breath sounds, added sounds, vocal resonance/fremitus).', 'examination', 'clinical_method', '{"what_is_it": "chest examination sequence (inspect-feel-percuss-listen)", "source_support": "Hutchison 24e ch12 p183-189"}'::jsonb, 0.9),
   ('9446d12f-dd68-5437-93f7-5c902561d1c1', '65136da8-4dfd-5f3c-b1ca-4ca5c5149bd6', 'HCH12-0018', 'Auscultation interpretation (Box 12.16): vesicular breath sounds are normal; bronchial breath sounds indicate consolidation; whispering pectoriloquy indicates consolidation; aegophony indicates top of pleural effusion or consolidation; pleural rub is associated with infection; wheezes occur in asthma, COPD, infection and cardiac failure; crackles occur in pulmonary fibrosis, cardiac failure and COPD; crackles at the beginning of inspiration are common in COPD; localized loud coarse crackles may indicate bronchiectasis; fine late-inspiratory crackles are characteristic of diffuse interstitial fibrosis.', 'examination', 'clinical_method', '{"what_is_it": "auscultation finding → pathology interpretation map", "what_fact_produces": "breath sound interpretation facts", "source_support": "Hutchison 24e ch12 p187-188 Box 12.16"}'::jsonb, 0.9),
   ('c25a99d2-bee0-529f-abca-323fbed2efb1', 'b30fc29e-f9c8-5f67-9204-80ae103db2a4', 'HCH12-0019', 'Tracheal deviation interpretation: deviation of trachea or cardiac impulse away from the affected side suggests a pleural effusion or pneumothorax (mediastinum pushed); deviation towards the affected side suggests fibrosis or collapse (mediastinum pulled); displacement of cardiac impulse without tracheal displacement may be scoliosis, funnel chest or left ventricular enlargement.', 'differential', 'clinical_method', '{"what_is_it": "tracheal/cardiac displacement differential", "source_support": "Hutchison 24e ch12 p186"}'::jsonb, 0.9),
   ('e4eb64d9-491f-5b97-9b60-7f072f461b38', '84b86844-5df6-5504-b4cb-b7f9ab74644c', 'HCH12-0020', 'Box 12.5 important questions in chronic cough: recent cold/sore throat/viral infection; history of asthma, nocturnal cough or wheeze; nasal discharge or sinusitis; acid reflux/indigestion or coughing after meals; what time of day is the cough worse; do you smoke; are you breathless; have you coughed up blood; hoarse voice; fevers or night sweats; weight loss; chest pain.', 'question', 'clinical_method', '{"what_is_it": "chronic cough question set", "question_mode": "DIRECT", "what_fact_produces": "chronic cough red-flag and cause-eliciting facts", "source_support": "Hutchison 24e ch12 p179 Box 12.5"}'::jsonb, 0.9),
   ('bd71b606-5d1e-59ae-bf4c-307d6dd6758b', '84b86844-5df6-5504-b4cb-b7f9ab74644c', 'HCH12-0021', 'MRC dyspnoea scale (Box 12.2): 1=not troubled except on strenuous exercise; 2=short of breath when hurrying or walking up a slight hill; 3=walks slower than contemporaries on the level because of breathlessness or stops for breath at own pace; 4=stops for breath after about 100 m or a few minutes on the level; 5=too breathless to leave the house or breathless when dressing/undressing.', 'threshold', 'clinical_method', '{"what_is_it": "MRC dyspnoea grading scale", "what_fact_produces": "MRC_DYSPNOEA_GRADE", "source_support": "Hutchison 24e ch12 p178 Box 12.2"}'::jsonb, 0.9)
